-- OpenConcept Core schema v3 for PostgreSQL.

-- The identifier prefix placeholder is expanded only after the runtime prefix is validated.

-- This file contains Core-owned tables only. Plugin tables are provisioned separately.



CREATE TABLE IF NOT EXISTS "{{OPENCONCEPT_PREFIX}}users" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "name" VARCHAR(120) NOT NULL,
    "email" VARCHAR(190) NOT NULL UNIQUE,
    "password_hash" VARCHAR(255) NOT NULL,
    "avatar_color" VARCHAR(7) NOT NULL DEFAULT '#5E6AD2',
    "avatar_kind" VARCHAR(16) NOT NULL DEFAULT 'initials',
    "avatar_value" VARCHAR(255) NOT NULL DEFAULT '',
    "ui_locale" VARCHAR(35) NOT NULL DEFAULT 'ja-JP',
    "role" VARCHAR(40) NOT NULL DEFAULT 'editor',
    "department" VARCHAR(120) NOT NULL DEFAULT 'プロダクト',
    "active" SMALLINT NOT NULL DEFAULT 1,
    "must_change_password" SMALLINT NOT NULL DEFAULT 0,
    "invited_at" TIMESTAMP WITHOUT TIME ZONE NULL,
    "last_login_at" TIMESTAMP WITHOUT TIME ZONE NULL,
    "created_at" TIMESTAMP WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS "{{OPENCONCEPT_PREFIX}}pages" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "parent_id" BIGINT NULL,
    "sort_order" INTEGER NOT NULL DEFAULT 0,
    "title" VARCHAR(240) NOT NULL DEFAULT '無題',
    "icon" VARCHAR(32) NOT NULL DEFAULT '📄',
    "cover" VARCHAR(32) NOT NULL DEFAULT 'mint',
    "status" VARCHAR(32) NOT NULL DEFAULT 'draft',
    "category" VARCHAR(120) NOT NULL DEFAULT 'ナレッジ',
    "tags_json" JSONB NOT NULL,
    "manual_tags_json" JSONB NULL,
    "blocks_json" JSONB NOT NULL,
    "plain_text" TEXT NOT NULL,
    "visibility" VARCHAR(32) NOT NULL DEFAULT 'company',
    "access_department" VARCHAR(120) NOT NULL DEFAULT '',
    "comments_enabled" SMALLINT NOT NULL DEFAULT 1,
    "language_code" VARCHAR(35) NOT NULL DEFAULT 'und',
    "translation_group_id" VARCHAR(64) NULL,
    "source_page_id" BIGINT NULL,
    "source_revision" BIGINT NULL,
    "translation_status" VARCHAR(32) NOT NULL DEFAULT 'original',
    "translation_block_map_json" JSONB NULL,
    "content_revision" BIGINT NOT NULL DEFAULT 1,
    "author_id" BIGINT NOT NULL,
    "updated_by" BIGINT NOT NULL,
    "is_favorite" SMALLINT NOT NULL DEFAULT 0,
    "archived_at" TIMESTAMP WITHOUT TIME ZONE NULL,
    "created_at" TIMESTAMP WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMP WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "published_at" TIMESTAMP WITHOUT TIME ZONE NULL,
    CONSTRAINT "{{OPENCONCEPT_PREFIX}}f_001" FOREIGN KEY (parent_id) REFERENCES "{{OPENCONCEPT_PREFIX}}pages"(id) ON DELETE SET NULL DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT "{{OPENCONCEPT_PREFIX}}f_002" FOREIGN KEY (author_id) REFERENCES "{{OPENCONCEPT_PREFIX}}users"(id) DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT "{{OPENCONCEPT_PREFIX}}f_003" FOREIGN KEY (updated_by) REFERENCES "{{OPENCONCEPT_PREFIX}}users"(id) DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT "{{OPENCONCEPT_PREFIX}}f_004" FOREIGN KEY (source_page_id) REFERENCES "{{OPENCONCEPT_PREFIX}}pages"(id) ON DELETE SET NULL DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE IF NOT EXISTS "{{OPENCONCEPT_PREFIX}}page_access_members" (
    "page_id" BIGINT NOT NULL,
    "user_id" BIGINT NOT NULL,
    "granted_by" BIGINT NOT NULL,
    "created_at" TIMESTAMP WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (page_id, user_id),
    CONSTRAINT "{{OPENCONCEPT_PREFIX}}f_005" FOREIGN KEY (page_id) REFERENCES "{{OPENCONCEPT_PREFIX}}pages"(id) ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT "{{OPENCONCEPT_PREFIX}}f_006" FOREIGN KEY (user_id) REFERENCES "{{OPENCONCEPT_PREFIX}}users"(id) ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT "{{OPENCONCEPT_PREFIX}}f_007" FOREIGN KEY (granted_by) REFERENCES "{{OPENCONCEPT_PREFIX}}users"(id) DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE IF NOT EXISTS "{{OPENCONCEPT_PREFIX}}page_access_departments" (
    "page_id" BIGINT NOT NULL,
    "department" VARCHAR(120) NOT NULL,
    "granted_by" BIGINT NOT NULL,
    "created_at" TIMESTAMP WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (page_id, department),
    CONSTRAINT "{{OPENCONCEPT_PREFIX}}f_008" FOREIGN KEY (page_id) REFERENCES "{{OPENCONCEPT_PREFIX}}pages"(id) ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT "{{OPENCONCEPT_PREFIX}}f_009" FOREIGN KEY (granted_by) REFERENCES "{{OPENCONCEPT_PREFIX}}users"(id) DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE IF NOT EXISTS "{{OPENCONCEPT_PREFIX}}page_public_shares" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "root_page_id" BIGINT NOT NULL,
    "token" VARCHAR(43) NOT NULL,
    "public_slug" VARCHAR(80) NULL,
    "enabled" SMALLINT NOT NULL DEFAULT 0,
    "publication_locale" VARCHAR(35) NULL,
    "revision" BIGINT NOT NULL DEFAULT 1,
    "published_revision" BIGINT NULL,
    "manifest_json" TEXT NULL,
    "source_hash" VARCHAR(64) NULL,
    "published_at" TIMESTAMP WITHOUT TIME ZONE NULL,
    "operation_state" VARCHAR(16) NOT NULL DEFAULT 'idle',
    "operation_id" VARCHAR(80) NULL,
    "pending_manifest_json" TEXT NULL,
    "operation_started_at" TIMESTAMP WITHOUT TIME ZONE NULL,
    "created_by" BIGINT NOT NULL,
    "updated_by" BIGINT NOT NULL,
    "created_at" TIMESTAMP WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMP WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "{{OPENCONCEPT_PREFIX}}f_010" FOREIGN KEY (root_page_id) REFERENCES "{{OPENCONCEPT_PREFIX}}pages"(id) ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT "{{OPENCONCEPT_PREFIX}}f_011" FOREIGN KEY (created_by) REFERENCES "{{OPENCONCEPT_PREFIX}}users"(id) DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT "{{OPENCONCEPT_PREFIX}}f_012" FOREIGN KEY (updated_by) REFERENCES "{{OPENCONCEPT_PREFIX}}users"(id) DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT "{{OPENCONCEPT_PREFIX}}c_001" CHECK (CHAR_LENGTH(token) = 43),
    CONSTRAINT "{{OPENCONCEPT_PREFIX}}c_002" CHECK (revision > 0),
    CONSTRAINT "{{OPENCONCEPT_PREFIX}}u_001" UNIQUE (root_page_id),
    CONSTRAINT "{{OPENCONCEPT_PREFIX}}u_002" UNIQUE (token),
    CONSTRAINT "{{OPENCONCEPT_PREFIX}}u_003" UNIQUE (public_slug)
);

CREATE TABLE IF NOT EXISTS "{{OPENCONCEPT_PREFIX}}page_public_share_pages" (
    "share_id" BIGINT NOT NULL,
    "page_id" BIGINT NOT NULL,
    "added_by" BIGINT NOT NULL,
    "created_at" TIMESTAMP WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (share_id, page_id),
    CONSTRAINT "{{OPENCONCEPT_PREFIX}}f_013" FOREIGN KEY (share_id) REFERENCES "{{OPENCONCEPT_PREFIX}}page_public_shares"(id) ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT "{{OPENCONCEPT_PREFIX}}f_014" FOREIGN KEY (page_id) REFERENCES "{{OPENCONCEPT_PREFIX}}pages"(id) ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT "{{OPENCONCEPT_PREFIX}}f_015" FOREIGN KEY (added_by) REFERENCES "{{OPENCONCEPT_PREFIX}}users"(id) DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE IF NOT EXISTS "{{OPENCONCEPT_PREFIX}}revisions" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "page_id" BIGINT NOT NULL,
    "title" VARCHAR(240) NOT NULL,
    "icon" VARCHAR(32) NOT NULL,
    "blocks_json" JSONB NOT NULL,
    "meta_json" JSONB NOT NULL,
    "created_by" BIGINT NOT NULL,
    "created_at" TIMESTAMP WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "{{OPENCONCEPT_PREFIX}}f_016" FOREIGN KEY (page_id) REFERENCES "{{OPENCONCEPT_PREFIX}}pages"(id) ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT "{{OPENCONCEPT_PREFIX}}f_017" FOREIGN KEY (created_by) REFERENCES "{{OPENCONCEPT_PREFIX}}users"(id) DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE IF NOT EXISTS "{{OPENCONCEPT_PREFIX}}comments" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "page_id" BIGINT NOT NULL,
    "parent_id" BIGINT NULL,
    "user_id" BIGINT NOT NULL,
    "body" TEXT NOT NULL,
    "resolved_at" TIMESTAMP WITHOUT TIME ZONE NULL,
    "edited_at" TIMESTAMP WITHOUT TIME ZONE NULL,
    "created_at" TIMESTAMP WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "{{OPENCONCEPT_PREFIX}}f_018" FOREIGN KEY (page_id) REFERENCES "{{OPENCONCEPT_PREFIX}}pages"(id) ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT "{{OPENCONCEPT_PREFIX}}f_019" FOREIGN KEY (parent_id) REFERENCES "{{OPENCONCEPT_PREFIX}}comments"(id) ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT "{{OPENCONCEPT_PREFIX}}f_020" FOREIGN KEY (user_id) REFERENCES "{{OPENCONCEPT_PREFIX}}users"(id) DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE IF NOT EXISTS "{{OPENCONCEPT_PREFIX}}notifications" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "user_id" BIGINT NOT NULL,
    "type" VARCHAR(40) NOT NULL,
    "message" VARCHAR(500) NOT NULL,
    "page_id" BIGINT NULL,
    "is_read" SMALLINT NOT NULL DEFAULT 0,
    "created_at" TIMESTAMP WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "{{OPENCONCEPT_PREFIX}}f_021" FOREIGN KEY (user_id) REFERENCES "{{OPENCONCEPT_PREFIX}}users"(id) ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT "{{OPENCONCEPT_PREFIX}}f_022" FOREIGN KEY (page_id) REFERENCES "{{OPENCONCEPT_PREFIX}}pages"(id) ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE IF NOT EXISTS "{{OPENCONCEPT_PREFIX}}audit_logs" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "user_id" BIGINT NOT NULL,
    "action" VARCHAR(80) NOT NULL,
    "subject_type" VARCHAR(80) NOT NULL,
    "subject_id" BIGINT NOT NULL,
    "detail_json" JSONB NOT NULL,
    "created_at" TIMESTAMP WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "{{OPENCONCEPT_PREFIX}}f_023" FOREIGN KEY (user_id) REFERENCES "{{OPENCONCEPT_PREFIX}}users"(id) DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE IF NOT EXISTS "{{OPENCONCEPT_PREFIX}}system_settings" (
    "setting_key" VARCHAR(120) PRIMARY KEY,
    "setting_value" TEXT NOT NULL,
    "updated_at" TIMESTAMP WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS "{{OPENCONCEPT_PREFIX}}rag_route_state" (
    "route_key" VARCHAR(64) PRIMARY KEY,
    "mode" VARCHAR(32) NOT NULL,
    "current_path" VARCHAR(32) NOT NULL,
    "future_generation" VARCHAR(190) NULL,
    "config_revision" BIGINT NOT NULL,
    "rollback_readiness" VARCHAR(32) NOT NULL,
    "created_at" TIMESTAMP WITHOUT TIME ZONE NOT NULL,
    "updated_at" TIMESTAMP WITHOUT TIME ZONE NOT NULL
);

CREATE TABLE IF NOT EXISTS "{{OPENCONCEPT_PREFIX}}rag_route_audit" (
    "route_key" VARCHAR(64) NOT NULL,
    "config_revision" BIGINT NOT NULL,
    "previous_revision" BIGINT NOT NULL,
    "actor_kind" VARCHAR(32) NOT NULL,
    "actor_user_id" BIGINT NULL,
    "transition_kind" VARCHAR(64) NOT NULL,
    "previous_state_json" TEXT NULL,
    "next_state_json" TEXT NOT NULL,
    "metadata_json" TEXT NOT NULL,
    "created_at" TIMESTAMP WITHOUT TIME ZONE NOT NULL,
    PRIMARY KEY (route_key, config_revision)
);

CREATE TABLE IF NOT EXISTS "{{OPENCONCEPT_PREFIX}}rag_index_engines" (
    "engine_instance_id" VARCHAR(64) PRIMARY KEY,
    "plugin_id" VARCHAR(64) NOT NULL,
    "configuration_json" TEXT NOT NULL,
    "enabled" SMALLINT NOT NULL DEFAULT 0,
    "status" VARCHAR(32) NOT NULL DEFAULT 'disabled',
    "active_generation_id" VARCHAR(68) NULL,
    "created_at" TIMESTAMP WITHOUT TIME ZONE NOT NULL,
    "updated_at" TIMESTAMP WITHOUT TIME ZONE NOT NULL
);

CREATE TABLE IF NOT EXISTS "{{OPENCONCEPT_PREFIX}}rag_index_generations" (
    "index_generation_id" VARCHAR(68) PRIMARY KEY,
    "engine_instance_id" VARCHAR(64) NOT NULL,
    "engine_plugin_id" VARCHAR(64) NULL,
    "engine_plugin_version" VARCHAR(64) NULL,
    "chunker_id" VARCHAR(128) NULL,
    "chunker_version" VARCHAR(64) NULL,
    "embedding_provider_id" VARCHAR(128) NULL,
    "embedding_model_id" VARCHAR(190) NULL,
    "embedding_model_revision" VARCHAR(190) NULL,
    "embedding_dimensions" INTEGER NULL,
    "distance_metric" VARCHAR(32) NULL,
    "configuration_json" TEXT NOT NULL,
    "source_snapshot_json" TEXT NOT NULL,
    "metrics_json" TEXT NOT NULL,
    "failure_code" VARCHAR(120) NULL,
    "status" VARCHAR(32) NOT NULL,
    "activated_at" TIMESTAMP WITHOUT TIME ZONE NULL,
    "created_at" TIMESTAMP WITHOUT TIME ZONE NOT NULL
);

CREATE TABLE IF NOT EXISTS "{{OPENCONCEPT_PREFIX}}rag_index_sync" (
    "engine_instance_id" VARCHAR(64) NOT NULL,
    "document_id" VARCHAR(160) NOT NULL,
    "revision_id" VARCHAR(160) NOT NULL,
    "content_hash" VARCHAR(64) NOT NULL,
    "indexed_at" TIMESTAMP WITHOUT TIME ZONE NULL,
    "status" VARCHAR(32) NOT NULL,
    "error_code" VARCHAR(120) NULL,
    "updated_at" TIMESTAMP WITHOUT TIME ZONE NOT NULL,
    PRIMARY KEY (engine_instance_id, document_id)
);

CREATE TABLE IF NOT EXISTS "{{OPENCONCEPT_PREFIX}}rag_index_jobs" (
    "job_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY,
    "engine_instance_id" VARCHAR(64) NOT NULL,
    "index_generation_id" VARCHAR(68) NULL,
    "job_type" VARCHAR(32) NOT NULL,
    "target_id" VARCHAR(160) NOT NULL,
    "revision_id" VARCHAR(160) NOT NULL,
    "content_hash" VARCHAR(64) NOT NULL,
    "snapshot_fingerprint" VARCHAR(64) NOT NULL,
    "indexed_items" INTEGER NOT NULL DEFAULT 0,
    "status" VARCHAR(32) NOT NULL DEFAULT 'queued',
    "attempts" INTEGER NOT NULL DEFAULT 0,
    "max_attempts" INTEGER NOT NULL DEFAULT 3,
    "next_retry_at" TIMESTAMP WITHOUT TIME ZONE NOT NULL,
    "locked_at" TIMESTAMP WITHOUT TIME ZONE NULL,
    "locked_by" VARCHAR(120) NULL,
    "error_code" VARCHAR(120) NULL,
    "created_at" TIMESTAMP WITHOUT TIME ZONE NOT NULL,
    "updated_at" TIMESTAMP WITHOUT TIME ZONE NOT NULL,
    "completed_at" TIMESTAMP WITHOUT TIME ZONE NULL,
    CONSTRAINT "{{OPENCONCEPT_PREFIX}}u_004" UNIQUE ( engine_instance_id, index_generation_id, job_type, target_id, revision_id, snapshot_fingerprint )
);

CREATE TABLE IF NOT EXISTS "{{OPENCONCEPT_PREFIX}}rag_index_runs" (
    "run_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY,
    "engine_instance_id" VARCHAR(64) NOT NULL,
    "query_hash" VARCHAR(64) NOT NULL,
    "status" VARCHAR(32) NOT NULL,
    "started_at" TIMESTAMP WITHOUT TIME ZONE NOT NULL,
    "completed_at" TIMESTAMP WITHOUT TIME ZONE NULL,
    "error_code" VARCHAR(120) NULL
);

CREATE TABLE IF NOT EXISTS "{{OPENCONCEPT_PREFIX}}rag_settings" (
    "setting_key" VARCHAR(120) PRIMARY KEY,
    "setting_value" TEXT NOT NULL,
    "updated_at" TIMESTAMP WITHOUT TIME ZONE NOT NULL
);

CREATE TABLE IF NOT EXISTS "{{OPENCONCEPT_PREFIX}}files" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "original_name" VARCHAR(255) NOT NULL,
    "stored_name" VARCHAR(96) NOT NULL UNIQUE,
    "mime_type" VARCHAR(160) NOT NULL,
    "category" VARCHAR(32) NOT NULL,
    "size_bytes" BIGINT NOT NULL,
    "uploaded_by" BIGINT NOT NULL,
    "page_id" BIGINT NULL,
    "created_at" TIMESTAMP WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "{{OPENCONCEPT_PREFIX}}f_024" FOREIGN KEY (uploaded_by) REFERENCES "{{OPENCONCEPT_PREFIX}}users"(id) DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT "{{OPENCONCEPT_PREFIX}}f_025" FOREIGN KEY (page_id) REFERENCES "{{OPENCONCEPT_PREFIX}}pages"(id) ON DELETE SET NULL DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE IF NOT EXISTS "{{OPENCONCEPT_PREFIX}}ai_conversations" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "user_id" BIGINT NOT NULL,
    "title" VARCHAR(240) NOT NULL DEFAULT '新しいチャット',
    "turn_count" BIGINT NOT NULL DEFAULT 0,
    "last_page_id" BIGINT NULL,
    "last_page_title" VARCHAR(240) NOT NULL DEFAULT '',
    "created_at" TIMESTAMP WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMP WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "archived_at" TIMESTAMP WITHOUT TIME ZONE NULL,
    CONSTRAINT "{{OPENCONCEPT_PREFIX}}f_026" FOREIGN KEY (user_id) REFERENCES "{{OPENCONCEPT_PREFIX}}users"(id) ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT "{{OPENCONCEPT_PREFIX}}f_027" FOREIGN KEY (last_page_id) REFERENCES "{{OPENCONCEPT_PREFIX}}pages"(id) ON DELETE SET NULL DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE IF NOT EXISTS "{{OPENCONCEPT_PREFIX}}ai_chat_turns" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "conversation_id" BIGINT NOT NULL,
    "turn_index" BIGINT NOT NULL,
    "mode" VARCHAR(24) NOT NULL DEFAULT 'search',
    "question" TEXT NOT NULL,
    "answer" TEXT NOT NULL,
    "page_id" BIGINT NULL,
    "page_title" VARCHAR(240) NOT NULL DEFAULT '',
    "sufficient" SMALLINT NOT NULL DEFAULT 0,
    "sources_json" JSONB NOT NULL,
    "candidate_count" BIGINT NOT NULL DEFAULT 0,
    "model" VARCHAR(120) NOT NULL DEFAULT '',
    "reasoning_effort" VARCHAR(16) NOT NULL DEFAULT 'low',
    "response_id" VARCHAR(190) NOT NULL DEFAULT '',
    "input_tokens" BIGINT NOT NULL DEFAULT 0,
    "output_tokens" BIGINT NOT NULL DEFAULT 0,
    "latency_ms" BIGINT NOT NULL DEFAULT 0,
    "degraded" SMALLINT NOT NULL DEFAULT 0,
    "review_status" VARCHAR(24) NOT NULL DEFAULT 'pending',
    "review_note" TEXT NULL,
    "reviewed_by" BIGINT NULL,
    "reviewed_at" TIMESTAMP WITHOUT TIME ZONE NULL,
    "created_at" TIMESTAMP WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "{{OPENCONCEPT_PREFIX}}f_028" FOREIGN KEY (conversation_id) REFERENCES "{{OPENCONCEPT_PREFIX}}ai_conversations"(id) ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT "{{OPENCONCEPT_PREFIX}}f_029" FOREIGN KEY (page_id) REFERENCES "{{OPENCONCEPT_PREFIX}}pages"(id) ON DELETE SET NULL DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT "{{OPENCONCEPT_PREFIX}}f_030" FOREIGN KEY (reviewed_by) REFERENCES "{{OPENCONCEPT_PREFIX}}users"(id) ON DELETE SET NULL DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT "{{OPENCONCEPT_PREFIX}}u_005" UNIQUE (conversation_id, turn_index)
);

CREATE TABLE IF NOT EXISTS "{{OPENCONCEPT_PREFIX}}rag_source_documents" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "page_id" BIGINT NOT NULL,
    "source_hash" VARCHAR(64) NOT NULL,
    "source_schema_version" INTEGER NOT NULL DEFAULT 4,
    "title" VARCHAR(240) NOT NULL,
    "category" VARCHAR(120) NOT NULL,
    "tags_json" JSONB NOT NULL,
    "blocks_json" JSONB NOT NULL,
    "plain_text" TEXT NOT NULL,
    "visibility" VARCHAR(32) NOT NULL,
    "access_department" VARCHAR(120) NOT NULL DEFAULT '',
    "author_id" BIGINT NOT NULL,
    "updated_by" BIGINT NOT NULL,
    "source_created_at" TIMESTAMP WITHOUT TIME ZONE NOT NULL,
    "source_updated_at" TIMESTAMP WITHOUT TIME ZONE NOT NULL,
    "published_at" TIMESTAMP WITHOUT TIME ZONE NULL,
    "language_code" VARCHAR(35) NOT NULL DEFAULT 'und',
    "translation_group_id" VARCHAR(64) NULL,
    "source_page_id" BIGINT NULL,
    "translation_role" VARCHAR(16) NOT NULL DEFAULT 'original',
    "translation_status" VARCHAR(32) NOT NULL DEFAULT 'original',
    "source_revision" BIGINT NULL,
    "content_revision" BIGINT NOT NULL DEFAULT 1,
    "is_current" SMALLINT NOT NULL DEFAULT 1,
    "captured_at" TIMESTAMP WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "{{OPENCONCEPT_PREFIX}}f_031" FOREIGN KEY (page_id) REFERENCES "{{OPENCONCEPT_PREFIX}}pages"(id) ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT "{{OPENCONCEPT_PREFIX}}f_032" FOREIGN KEY (author_id) REFERENCES "{{OPENCONCEPT_PREFIX}}users"(id) DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT "{{OPENCONCEPT_PREFIX}}f_033" FOREIGN KEY (updated_by) REFERENCES "{{OPENCONCEPT_PREFIX}}users"(id) DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT "{{OPENCONCEPT_PREFIX}}u_006" UNIQUE (page_id, source_hash)
);

CREATE TABLE IF NOT EXISTS "{{OPENCONCEPT_PREFIX}}rag_source_units" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "source_document_id" BIGINT NOT NULL,
    "unit_index" BIGINT NOT NULL,
    "unit_key" VARCHAR(190) NOT NULL,
    "block_type" VARCHAR(40) NOT NULL,
    "heading_path_json" JSONB NOT NULL,
    "content" TEXT NOT NULL,
    "content_sha256" VARCHAR(64) NOT NULL,
    "char_count" BIGINT NOT NULL,
    CONSTRAINT "{{OPENCONCEPT_PREFIX}}f_034" FOREIGN KEY (source_document_id) REFERENCES "{{OPENCONCEPT_PREFIX}}rag_source_documents"(id) ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT "{{OPENCONCEPT_PREFIX}}u_007" UNIQUE (source_document_id, unit_index),
    CONSTRAINT "{{OPENCONCEPT_PREFIX}}u_008" UNIQUE (source_document_id, unit_key)
);

CREATE TABLE IF NOT EXISTS "{{OPENCONCEPT_PREFIX}}rag_source_access_members" (
    "source_document_id" BIGINT NOT NULL,
    "user_id" BIGINT NOT NULL,
    PRIMARY KEY (source_document_id, user_id),
    CONSTRAINT "{{OPENCONCEPT_PREFIX}}f_035" FOREIGN KEY (source_document_id) REFERENCES "{{OPENCONCEPT_PREFIX}}rag_source_documents"(id) ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT "{{OPENCONCEPT_PREFIX}}f_036" FOREIGN KEY (user_id) REFERENCES "{{OPENCONCEPT_PREFIX}}users"(id) ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE IF NOT EXISTS "{{OPENCONCEPT_PREFIX}}rag_source_access_departments" (
    "source_document_id" BIGINT NOT NULL,
    "department" VARCHAR(120) NOT NULL,
    PRIMARY KEY (source_document_id, department),
    CONSTRAINT "{{OPENCONCEPT_PREFIX}}f_037" FOREIGN KEY (source_document_id) REFERENCES "{{OPENCONCEPT_PREFIX}}rag_source_documents"(id) ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE IF NOT EXISTS "{{OPENCONCEPT_PREFIX}}rag_jobs" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "page_id" BIGINT NOT NULL,
    "source_hash" VARCHAR(64) NOT NULL,
    "prompt_version" VARCHAR(80) NOT NULL,
    "status" VARCHAR(24) NOT NULL DEFAULT 'queued',
    "reasoning_effort" VARCHAR(16) NOT NULL DEFAULT 'medium',
    "attempts" INTEGER NOT NULL DEFAULT 0,
    "max_attempts" INTEGER NOT NULL DEFAULT 3,
    "available_at" TIMESTAMP WITHOUT TIME ZONE NOT NULL,
    "locked_at" TIMESTAMP WITHOUT TIME ZONE NULL,
    "locked_by" VARCHAR(190) NULL,
    "last_error" TEXT NULL,
    "created_at" TIMESTAMP WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMP WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "completed_at" TIMESTAMP WITHOUT TIME ZONE NULL,
    CONSTRAINT "{{OPENCONCEPT_PREFIX}}f_038" FOREIGN KEY (page_id) REFERENCES "{{OPENCONCEPT_PREFIX}}pages"(id) ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT "{{OPENCONCEPT_PREFIX}}u_009" UNIQUE (page_id, source_hash, prompt_version)
);

CREATE TABLE IF NOT EXISTS "{{OPENCONCEPT_PREFIX}}rag_page_profiles" (
    "page_id" BIGINT PRIMARY KEY,
    "source_hash" VARCHAR(64) NOT NULL,
    "language" VARCHAR(40) NOT NULL,
    "summary" TEXT NOT NULL,
    "short_summary" TEXT NOT NULL,
    "tags_json" JSONB NOT NULL,
    "keywords_json" JSONB NOT NULL,
    "entities_json" JSONB NOT NULL,
    "questions_json" JSONB NOT NULL,
    "model" VARCHAR(120) NOT NULL,
    "reasoning_effort" VARCHAR(16) NOT NULL,
    "prompt_version" VARCHAR(80) NOT NULL,
    "response_id" VARCHAR(190) NOT NULL DEFAULT '',
    "input_chars" BIGINT NOT NULL DEFAULT 0,
    "input_tokens" BIGINT NOT NULL DEFAULT 0,
    "output_tokens" BIGINT NOT NULL DEFAULT 0,
    "latency_ms" BIGINT NOT NULL DEFAULT 0,
    "analyzed_at" TIMESTAMP WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "{{OPENCONCEPT_PREFIX}}f_039" FOREIGN KEY (page_id) REFERENCES "{{OPENCONCEPT_PREFIX}}pages"(id) ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE IF NOT EXISTS "{{OPENCONCEPT_PREFIX}}rag_chunks" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "page_id" BIGINT NOT NULL,
    "source_hash" VARCHAR(64) NOT NULL,
    "prompt_version" VARCHAR(80) NOT NULL,
    "chunk_index" BIGINT NOT NULL,
    "chunk_key" VARCHAR(64) NOT NULL,
    "title" VARCHAR(240) NOT NULL,
    "heading_path_json" JSONB NOT NULL,
    "unit_ids_json" JSONB NOT NULL,
    "content" TEXT NOT NULL,
    "chunk_summary" TEXT NOT NULL,
    "keywords_json" JSONB NOT NULL,
    "search_text" TEXT NOT NULL,
    "token_estimate" BIGINT NOT NULL DEFAULT 0,
    "char_count" BIGINT NOT NULL DEFAULT 0,
    "model" VARCHAR(120) NOT NULL,
    "reasoning_effort" VARCHAR(16) NOT NULL,
    "is_active" SMALLINT NOT NULL DEFAULT 1,
    "created_at" TIMESTAMP WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMP WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "{{OPENCONCEPT_PREFIX}}f_040" FOREIGN KEY (page_id) REFERENCES "{{OPENCONCEPT_PREFIX}}pages"(id) ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT "{{OPENCONCEPT_PREFIX}}u_010" UNIQUE (page_id, source_hash, prompt_version, chunk_index)
);

CREATE TABLE IF NOT EXISTS "{{OPENCONCEPT_PREFIX}}rag_generated_tags" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "page_id" BIGINT NOT NULL,
    "source_hash" VARCHAR(64) NOT NULL,
    "prompt_version" VARCHAR(80) NOT NULL,
    "tag" VARCHAR(120) NOT NULL,
    "normalized_tag" VARCHAR(120) NOT NULL,
    "relevance" NUMERIC(5,4) NOT NULL DEFAULT 0,
    "model" VARCHAR(120) NOT NULL,
    "is_active" SMALLINT NOT NULL DEFAULT 1,
    "created_at" TIMESTAMP WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "{{OPENCONCEPT_PREFIX}}f_041" FOREIGN KEY (page_id) REFERENCES "{{OPENCONCEPT_PREFIX}}pages"(id) ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT "{{OPENCONCEPT_PREFIX}}u_011" UNIQUE (page_id, source_hash, prompt_version, normalized_tag)
);

CREATE TABLE IF NOT EXISTS "{{OPENCONCEPT_PREFIX}}rag_canonical_tags" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "canonical_name" VARCHAR(120) NOT NULL,
    "normalized_name" VARCHAR(190) NOT NULL,
    "tag_type" VARCHAR(40) NOT NULL DEFAULT 'general',
    "created_source" VARCHAR(16) NOT NULL DEFAULT 'ai',
    "created_at" TIMESTAMP WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMP WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "{{OPENCONCEPT_PREFIX}}u_012" UNIQUE (normalized_name)
);

CREATE TABLE IF NOT EXISTS "{{OPENCONCEPT_PREFIX}}rag_tag_aliases" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "tag_id" BIGINT NOT NULL,
    "alias" VARCHAR(120) NOT NULL,
    "normalized_alias" VARCHAR(190) NOT NULL,
    "created_source" VARCHAR(16) NOT NULL DEFAULT 'ai',
    "created_at" TIMESTAMP WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "{{OPENCONCEPT_PREFIX}}f_042" FOREIGN KEY (tag_id) REFERENCES "{{OPENCONCEPT_PREFIX}}rag_canonical_tags"(id) ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT "{{OPENCONCEPT_PREFIX}}u_013" UNIQUE (normalized_alias),
    CONSTRAINT "{{OPENCONCEPT_PREFIX}}u_014" UNIQUE (tag_id, normalized_alias)
);

CREATE TABLE IF NOT EXISTS "{{OPENCONCEPT_PREFIX}}rag_page_tag_links" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "page_id" BIGINT NOT NULL,
    "source_hash" VARCHAR(64) NOT NULL DEFAULT '',
    "prompt_version" VARCHAR(80) NOT NULL DEFAULT '',
    "tag_id" BIGINT NOT NULL,
    "metadata_field" VARCHAR(24) NOT NULL,
    "source" VARCHAR(16) NOT NULL,
    "confidence" NUMERIC(5,4) NULL,
    "is_active" SMALLINT NOT NULL DEFAULT 1,
    "created_at" TIMESTAMP WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMP WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "{{OPENCONCEPT_PREFIX}}f_043" FOREIGN KEY (page_id) REFERENCES "{{OPENCONCEPT_PREFIX}}pages"(id) ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT "{{OPENCONCEPT_PREFIX}}f_044" FOREIGN KEY (tag_id) REFERENCES "{{OPENCONCEPT_PREFIX}}rag_canonical_tags"(id) ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT "{{OPENCONCEPT_PREFIX}}u_015" UNIQUE (page_id, source_hash, prompt_version, tag_id, metadata_field, source)
);

CREATE TABLE IF NOT EXISTS "{{OPENCONCEPT_PREFIX}}rag_source_unit_blocks" (
    "source_unit_id" BIGINT PRIMARY KEY,
    "page_id" BIGINT NOT NULL,
    "block_id" VARCHAR(190) NOT NULL,
    "created_at" TIMESTAMP WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "{{OPENCONCEPT_PREFIX}}f_045" FOREIGN KEY (source_unit_id) REFERENCES "{{OPENCONCEPT_PREFIX}}rag_source_units"(id) ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT "{{OPENCONCEPT_PREFIX}}f_046" FOREIGN KEY (page_id) REFERENCES "{{OPENCONCEPT_PREFIX}}pages"(id) ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE IF NOT EXISTS "{{OPENCONCEPT_PREFIX}}rag_block_metadata" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "page_id" BIGINT NOT NULL,
    "source_hash" VARCHAR(64) NOT NULL,
    "prompt_version" VARCHAR(80) NOT NULL,
    "block_id" VARCHAR(190) NOT NULL,
    "block_type" VARCHAR(40) NOT NULL,
    "summary" TEXT NOT NULL,
    "keywords_json" JSONB NOT NULL,
    "entities_json" JSONB NOT NULL,
    "model" VARCHAR(120) NOT NULL,
    "is_active" SMALLINT NOT NULL DEFAULT 1,
    "created_at" TIMESTAMP WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMP WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "{{OPENCONCEPT_PREFIX}}f_047" FOREIGN KEY (page_id) REFERENCES "{{OPENCONCEPT_PREFIX}}pages"(id) ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT "{{OPENCONCEPT_PREFIX}}u_016" UNIQUE (page_id, source_hash, prompt_version, block_id)
);

CREATE TABLE IF NOT EXISTS "{{OPENCONCEPT_PREFIX}}rag_chunk_blocks" (
    "chunk_id" BIGINT NOT NULL,
    "page_id" BIGINT NOT NULL,
    "block_id" VARCHAR(190) NOT NULL,
    "source_hash" VARCHAR(64) NOT NULL,
