    CONSTRAINT "{{OPENCONCEPT_PREFIX}}f_048" FOREIGN KEY (chunk_id) REFERENCES "{{OPENCONCEPT_PREFIX}}rag_chunks"(id) ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT "{{OPENCONCEPT_PREFIX}}f_049" FOREIGN KEY (page_id) REFERENCES "{{OPENCONCEPT_PREFIX}}pages"(id) ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED
);



