-- Generation 6: Core-owned common plugin API data.
CREATE TABLE IF NOT EXISTS "{{OPENCONCEPT_PREFIX}}extension_records" (
    scope VARCHAR(64) NOT NULL,
    collection VARCHAR(64) NOT NULL,
    record_key VARCHAR(190) NOT NULL,
    payload_json TEXT NOT NULL,
    revision BIGINT NOT NULL,
    created_at BIGINT NOT NULL,
    updated_at BIGINT NOT NULL,
    PRIMARY KEY (scope, collection, record_key)
);

CREATE TABLE IF NOT EXISTS "{{OPENCONCEPT_PREFIX}}extension_jobs" (
    id VARCHAR(64) NOT NULL PRIMARY KEY,
    scope VARCHAR(64) NOT NULL,
    job_name VARCHAR(64) NOT NULL,
    dedupe_key VARCHAR(64) NOT NULL,
    payload_json TEXT NOT NULL,
    state VARCHAR(32) NOT NULL,
    attempts BIGINT NOT NULL,
    available_at BIGINT NOT NULL,
    lease_token VARCHAR(64) NULL,
    lease_until BIGINT NULL,
    last_error TEXT NULL,
    created_at BIGINT NOT NULL,
    updated_at BIGINT NOT NULL,
    UNIQUE (scope, dedupe_key)
);

CREATE TABLE IF NOT EXISTS "{{OPENCONCEPT_PREFIX}}extension_events" (
    id VARCHAR(64) NOT NULL PRIMARY KEY,
    event_name VARCHAR(64) NOT NULL,
    source_key VARCHAR(64) NOT NULL,
    payload_json TEXT NOT NULL,
    created_at BIGINT NOT NULL,
    UNIQUE (event_name, source_key)
);

CREATE TABLE IF NOT EXISTS "{{OPENCONCEPT_PREFIX}}extension_search_content" (
    id VARCHAR(64) NOT NULL PRIMARY KEY,
    scope VARCHAR(64) NOT NULL,
    source_type VARCHAR(64) NOT NULL,
    source_id VARCHAR(190) NOT NULL,
    source_version VARCHAR(128) NOT NULL,
    content_hash VARCHAR(64) NOT NULL,
    page_id BIGINT NULL,
    body_text TEXT NOT NULL,
    provenance_json TEXT NOT NULL,
    state VARCHAR(32) NOT NULL,
    revision BIGINT NOT NULL,
    created_at BIGINT NOT NULL,
    updated_at BIGINT NOT NULL
);
